import sys
from collections import defaultdict, deque

MOD = 10**9 + 7

def dfs(node, parent, graph, depth, red_count, black_count, dp):
    dp[node] = [1] * 5
    for neighbor, color, weight in graph[node]:
        if neighbor == parent:
            continue
        dfs(neighbor, node, graph, depth + 1, red_count + (color == 0), black_count + (color == 1), dp)
        for i in range(5):
            for j in range(5):
                if abs(i - j) <= 2:
                    dp[node][i] = (dp[node][i] * dp[neighbor][j] * weight) % MOD

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    edges = []
    index = 1
    for _ in range(n - 1):
        u = int(data[index]) - 1
        v = int(data[index + 1]) - 1
        x = int(data[index + 2])
        c = int(data[index + 3])
        edges.append((u, v, x, c))
        index += 4

    graph = defaultdict(list)
    for u, v, x, c in edges:
        graph[u].append((v, c, x))
        graph[v].append((u, c, x))

    dp = [[1] * 5 for _ in range(n)]
    dfs(0, -1, graph, 0, 0, 0, dp)

    result = 1
    for i in range(1, n):
        for j in range(5):
            result = (result * dp[i][j]) % MOD

    print(result)

if __name__ == "__main__":
    main()
